<?php require_once __DIR__.'/../includes/bootstrap.php';$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT c,u.name producer FROM casting_calls c JOIN users u ON u.id=c.user_id WHERE c.id=? AND c.status='open'");$s->execute([$id]);$job=$s->fetch();if(!$job){http_response_code(404);exit('Casting call not found.');}$me=current_user();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!$me){header('Location: '.url('auth/login.php'));exit;}verify_csrf();if($me['role']!=='talent')$error='Only talent accounts can apply.';else{try{$s=db()->prepare('INSERT INTO applications(casting_id,talent_id,note) VALUES(?,?,?)');$s->execute([$id,$me['id'],trim($_POST['note']??'')]);$error='Application submitted successfully.';}catch(PDOException $e){$error='You have already applied to this casting call.';}}}$pageTitle=$job['title'].' · CineCast';require __DIR__.'/../includes/header.php';?><main class="page-wrap"><div class="container"><div class="eyebrow dark"><?=e($job['project_type'])?> · <?=e($job['city'])?></div><h1 class="page-title"><?=e($job['title'])?></h1><div class="content-card"><div class="job-meta"><span>Posted by <?=e($job['producer'])?></span><?php if($job['deadline']):?><span>Deadline <?=e(date('d M Y',strtotime($job['deadline'])))?></span><?php endif;?></div><h2 style="font:600 30px var(--serif)">Role: <?=e($job['role_description'])?></h2><p><?=nl2br(e($job['description']))?></p><p><strong>Age range:</strong> <?=e($job['age_min']??'Any')?>–<?=e($job['age_max']??'Any')?> · <strong>Gender:</strong> <?=e($job['gender'])?></p><?php if($error):?><div class="alert success"><?=e($error)?></div><?php endif;?><?php if(!$me):?><a class="btn btn-primary" href="<?=e(url('auth/login.php'))?>">Log in to apply ↗</a><?php elseif($me['role']==='talent'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>INTRODUCE YOURSELF (OPTIONAL)</label><textarea name="note" placeholder="Tell the casting team why you're right for this role."></textarea></div><button class="btn btn-primary form-submit">Submit application ↗</button></form><?php endif;?></div></div></main><?php require __DIR__.'/../includes/footer.php'; ?>